website/src/components/AiQuickstart.astr.text:
---
interface Props { locale?: string }
const { locale = 'en' } = Astro.props;
import { createTranslator } from '../i18n/messages.mjs';
const t = createTranslator(locale);
import CopyBlock from './CopyBlock.astro';
import InstallCommand from './InstallCommand.astro';
import Icon from './Icon.astro';
import data from '../generated/ai-quickstart.json';
import { renderPrompt } from '../lib/ai-quickstart.mjs';
import { repository } from '../lib/site';
import { serializeClientMessages } from '../i18n/client-messages.mjs';
const requestMarker = '__ANKI_FORGE_TASK_INPUT__';
const clientTemplates = Object.fromEntries(Object.keys(data.languages).map(sdk => {
  const prompt = renderPrompt(data, sdk, requestMarker, locale);
  const split = prompt.split(requestMarker);
  if (split.length !== 2) throw new Error(`Expected one request placeholder: ${sdk}/${locale}`);
  return [sdk, { before: split[0], after: split[1], empty: renderPrompt(data, sdk, '', locale) }];
}));
---
<section data-module="ai-quickstart" id="ai-quickstart" class="ai-quickstart" data-ai-quickstart data-ai-locale={locale} aria-labelledby="ai-heading">
  <script is:inline type="application/json" data-ai-templates set:html={serializeClientMessages(clientTemplates)} />
  <div class="ai-intro">
    <h2 id="ai-heading">{t('ai.title')}</h2>
    <p>{t('ai.description')}</p>
    <div class="ai-request" data-ai-enhancement hidden>
      <label for="ai-request">{t('ai.request')}</label>
      <textarea id="ai-request" data-ai-request rows="5" placeholder={t('ai.placeholder')} aria-describedby="ai-request-hint"></textarea>
      <p id="ai-request-hint">{t('ai.privacy')}</p>
    </div>
    <p class="ai-skill-link">{t('ai.skillQuestion')}<br />
      <a class="text-link" href={`${repository}/tree/main/skills/anki-forge/`}>{t('ai.skillLink')} <Icon name="arrowUpRight" /></a>
    </p>
    <noscript><p class="ai-noscript">{t('ai.noScript')}</p></noscript>
  </div>
  <div class="ai-builder">
    <div class="example-tabs ai-tabs" role="tablist" aria-label={t('ai.language')} data-ai-enhancement hidden>
      {(['rust', 'node', 'python'] as const).map(key => [key, data.languages[key]] as const).map(([key, language], index) => (
        <button type="button" id={`ai-tab-${key}`} role="tab" data-ai-language={key} aria-selected={index === 0 ? 'true' : 'false'} aria-controls={`ai-panel-${key}`} tabindex={index === 0 ? 0 : -1}>{language.label}</button>
      ))}
    </div>
    {(['rust', 'node', 'python'] as const).map(key => [key, data.languages[key]] as const).map(([key, language]) => (
      <div id={`ai-panel-${key}`} data-ai-panel={key} class="ai-panel">
        <h3 class="ai-language-label">{language.label}</h3>
        <CopyBlock label={`${t('ai.brief')} · Anki Forge ${data.publicVersion}`} text={renderPrompt(data, key, '', locale)} aiPrompt
          buttonLabel={t('ai.copy')} success={t('ai.copied')}
          fallback={t('ai.fallback')} />
        <InstallCommand command={language.install} runtime={language.runtime} buttonLabel={t('ai.install')} locale={locale} />
      </div>
    ))}
  </div>
</section>

website/src/components/ArticlePage.astro.text:
---
import { render, type CollectionEntry } from 'astro:content';
import SiteLayout from '../layouts/SiteLayout.astro';
import { formatDate, sitePath } from '../lib/site';
import { pagePath } from '../../site-model.mjs';
import { createTranslator } from '../i18n/messages.mjs';
import { siteConfig } from '../../site.config.mjs';
import { canonicalUrl, markdownUrl } from '../lib/machine-urls.mjs';
interface Props { post: CollectionEntry<'blog'> }
const { post } = Astro.props;
const locale = post.data.locale;
const t = createTranslator(locale);
const { Content } = await render(post);
const markdown = markdownUrl({ id: `blog:${post.data.translationKey}`, type: 'article', locale, canonical: canonicalUrl(`blog:${post.data.translationKey}`, locale, siteConfig) });
---
<SiteLayout locale={locale} title={post.data.title} description={post.data.description} article publishedAt={post.data.date} category={t(`blog.${post.data.category}`)}>
  <article class="article container">
    <header class="article-header"><a class="text-link" href={sitePath(pagePath('blog', locale))}>{t('blog.all')}</a><h1>{post.data.title}</h1><p class="lede">{post.data.description}</p><div class="post-meta"><span>{t(`blog.${post.data.category}`)}</span><time datetime={post.data.date.toISOString()}>{formatDate(post.data.date, locale)}</time></div></header>
    <div class="prose" data-machine-content><Content /></div>
    <footer class="article-footer"><a class="text-link" href={markdown}>{t('machine.viewMarkdown')}</a> <a class="text-link" href={sitePath(pagePath('docs', locale))}>{t('blog.continue')}</a></footer>
  </article>
</SiteLayout>

website/src/components/BlogPage.astro.text:
---
import { getCollection } from 'astro:content';
import SiteLayout from '../layouts/SiteLayout.astro';
import PostCard from './PostCard.astro';
import { sitePath } from '../lib/site';
import { locales } from '../../site-model.mjs';
import { createTranslator } from '../i18n/messages.mjs';
interface Props { locale: string }
const { locale } = Astro.props;
const t = createTranslator(locale);
const posts = (await getCollection('blog', ({ data }) => !data.draft && data.locale === locale)).sort((a, b) => b.data.date.valueOf() - a.data.date.valueOf());
---
<SiteLayout locale={locale} title={t('blog.title')} description={t('blog.description')}>
  <div class="container">
    <header class="page-intro"><h1>{t('blog.heading')}</h1><p>{t('blog.description')}</p><a class="text-link" href={sitePath(`${locales[locale].prefix}/rss.xml`)}>{t('blog.rss')}</a></header>
    <div class="post-grid blog-list">{posts.map(post => <PostCard post={post} />)}</div>
  </div>
</SiteLayout>

website/src/components/CardPreview.astro.text:
---
import { createTranslator } from '../i18n/messages.mjs';
import type { CardExample } from '../lib/examples';
import { sitePath } from '../lib/site';
import Icon from './Icon.astro';
interface Props { example: CardExample; prefix: string; locale?: string }
const { example, prefix, locale = 'en' } = Astro.props;
const { clozeParts: cloze } = example;
const t = createTranslator(locale);
---
<div class="card-preview" data-card-preview>
  <div class="preview-label"><span>{example.deck}</span><Icon name="cards" /></div>
  <div class="flashcard" data-flashcard>
    <div class="flashcard-inner">
      <div class="flashcard-face" data-side="front">
        {example.id === 'basic' && <><span class="card-caption">{t('card.direction')}</span><p class="card-word">{example.front}</p><span class="card-caption">{t('card.meaning')}</span></>}
        {example.id === 'cloze' && cloze && <><span class="card-caption">{t('card.sentence')}</span><p class="card-sentence">{cloze[1]}<span class="cloze">[…]</span>{cloze[3]}</p></>}
        {example.id === 'media' && <><span class="card-caption">{t('card.ear')}</span><p class="card-prompt">{example.front}</p><img class="waveform" src={sitePath(`/generated/${example.image}`)} width="320" height="104" alt={t('card.waveform')} /></>}
        {example.id === 'occlusion' && <><span class="card-caption">{t('card.cell')}</span><p class="card-prompt">{example.front}</p><div class="occlusion-diagram"><img src={sitePath(`/generated/${example.image}`)} width={example.imageWidth} height={example.imageHeight} alt={t('card.hiddenCell')} /><span class="occlusion-cover" style={example.maskStyle} aria-hidden="true">?</span></div></>}
      </div>
