/** @type {{ id: string, label: Record<string, string> }[]} */
export const navigation = [
  { id: 'docs', label: { en: 'Guide', 'zh-CN': '指南' } },
  { id: 'examples', label: { en: 'Examples', 'zh-CN': '示例' } },
  { id: 'blog', label: { en: 'Blog', 'zh-CN': '博客' } },
];
export const footerNavigation = [
